import { goalOptions, labels } from "../data/member-options.js";
import { metricSections, metricDefinitions } from "../data/fitmao-metrics.js";
import { glossaryData, glossaryEntry } from "../data/glossary-data.js";
import { rankingNotice } from "../data/ranking-rules.js";
import { rankFocusAreas } from "../services/ranking-service.js";
import { explainFocus } from "../services/explanation-service.js";
import { compareAssessments } from "../services/comparison-service.js";
import { escapeHtml, label, formatDate, pageHeader, notice, professionalNotice, emptyState } from "../components/ui.js";
import { focusCard } from "../components/focus-card.js";
import { metricRow } from "../components/metric-row.js";
import { fictionalDemoProfile } from "../data/demo-data.js";
import { ACCEPTED_REPORT_LABEL } from "../services/report-import-service.js";

const latest=state=>state.assessments.at(-1);
const ranking=state=>state.latestResult?.ranking||rankFocusAreas(latest(state),state.profile);
const sourceNotice=()=>notice("This prototype demonstrates the automatic review flow with sample report details. It does not read the real QR code or screenshot yet. Replace the sample values with those shown on your FitMao report.","info","About this test step");
const stepper=(active,items=["Profile","Assessment","Results"])=>`<ol class="stepper" aria-label="Progress">${items.map((item,index)=>`<li class="${index+1===active?"is-active":index+1<active?"is-done":""}"><span>${index+1<active?"✓":index+1}</span><small>${item}</small></li>`).join("")}</ol>`;
const goalCards=(name,current)=>goalOptions.map(([value,title,help])=>`<label class="choice-card"><input type="radio" name="${name}" value="${value}" ${current===value?"checked":""}><span><strong>${title}</strong><small>${help}</small></span></label>`).join("");
const selectOptions=(values,current)=>values.map(value=>`<option value="${value}" ${current===value?"selected":""}>${labels[value]}</option>`).join("");
const valueText=m=>`${escapeHtml(m.value)}${m.unit&&m.unit!=="—"?` ${escapeHtml(m.unit)}`:""}`;
const metricFrom=(assessment,id)=>assessment?.metrics.find(metric=>metric.id===id&&metric.available!==false);
const historyValue=(assessment,id)=>{const metric=metricFrom(assessment,id);return metric?valueText(metric):"Not recorded"};
const historyCard=(assessment,state,isNewest)=>{const result=rankFocusAreas(assessment,state.profile),focus=result.mainFocus;return `<article class="history-card"><header><div class="history-date"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M8 3v4M16 3v4M3 10h18"/></svg><span>${formatDate(assessment.assessedAt)}</span></div>${isNewest?'<span class="history-latest">Newest</span>':""}</header><h3>FitMao assessment</h3><div class="history-metrics"><div><small>Body weight</small><strong>${historyValue(assessment,"weight")}</strong></div><div><small>Body fat</small><strong>${historyValue(assessment,"pbf")}</strong></div><div><small>Muscle mass</small><strong>${historyValue(assessment,"smm")}</strong></div></div><div class="history-focus"><small>Starting point</small><strong>${escapeHtml(focus?.label||"Review all report values")}</strong></div><a class="button button-light button-block" href="#/history/${escapeHtml(assessment.id)}">View interpreted results <span aria-hidden="true">→</span></a></article>`};
const sectionTitles={"Body Composition Analysis":"Body composition","Muscle-Fat Analysis":"Muscle and body fat","Obesity Analysis":"Weight and body fat","Segmental Assessment":"Body areas","Comprehensive Evaluation":"Additional measurements","Body Type and Weight Control":"Report summary and targets"};
const sectionTitle=section=>sectionTitles[section]||section;
const demographicFields=(a={})=>`<section class="card demographic-review"><div class="section-head"><div><p class="eyebrow">Captured report details</p><h2>Member and assessment</h2></div><span class="capture-state">Automatically filled</span></div><div class="demographic-grid"><div class="field"><label for="report-name">Name</label><input class="input" id="report-name" name="displayName" value="${escapeHtml(a.displayName||"")}"></div><div class="field"><label for="report-age">Age</label><input class="input" id="report-age" name="age" type="number" min="1" max="120" value="${escapeHtml(a.age||"")}"></div><div class="field"><label for="report-gender">Gender</label><input class="input" id="report-gender" name="gender" value="${escapeHtml(a.gender||"")}"></div><div class="field"><label for="report-height">Height</label><div class="input-with-unit"><input class="input" id="report-height" name="height" type="number" step="0.1" value="${escapeHtml(a.height||"")}"><span>cm</span></div></div><div class="field"><label for="report-date">Assessment date</label><input class="input" id="report-date" name="assessmentDate" type="date" value="${escapeHtml(a.assessmentDate||"")}"></div></div></section>`;
const sourcePreview=(url,fileName="")=>url?(fileName.toLowerCase().endsWith(".pdf")?`<object data="${escapeHtml(url)}" type="application/pdf" aria-label="Uploaded FitMao PDF preview"></object>`:`<img src="${escapeHtml(url)}" alt="Uploaded FitMao report preview" data-report-preview>`):`<img src="assets/images/sample-fitmao-report.svg" alt="Fictional FitMao report preview" data-report-preview>`;

export function welcomeView(){return `<main class="welcome automatic-welcome" id="main-content" tabindex="-1"><header class="welcome-nav"><a class="brand" href="#/welcome"><span class="brand-mark">FS</span><span>FITSTART</span></a><nav aria-label="Welcome links"><a href="#how-it-works">How it works</a><a href="#/glossary">Glossary</a><a href="#/sign-in">Sign in</a></nav></header><section class="welcome-import-hero"><div class="hero-copy"><p class="eyebrow">For new KSYN Fitness Alabang members</p><h1>Your body assessment,<br><em>explained clearly.</em></h1><p class="lead">FITSTART helps you understand your FitMao report and shows which information is most relevant to your fitness goal.</p><button class="text-button scope-link" data-action="open-boundaries">What FITSTART does and does not do</button></div><section class="welcome-import-panel" aria-labelledby="import-title"><p class="eyebrow">Start with your report</p><h2 id="import-title">Scan or upload</h2><p>Your report details will be filled in automatically for you to verify.</p><div class="welcome-report-actions"><button class="welcome-action" data-action="request-qr"><span aria-hidden="true">⌗</span><strong>Scan FitMao QR</strong><small>Use your phone camera</small></button><button class="welcome-action" data-action="request-upload" data-upload-input="welcome-report-upload"><span aria-hidden="true">⇧</span><strong>Upload FitMao Report</strong><small>Choose a report file</small></button></div><input class="visually-hidden" id="welcome-report-upload" type="file" accept="image/png,image/jpeg,application/pdf"><p class="accepted-files">${ACCEPTED_REPORT_LABEL}</p><div class="welcome-fallbacks"><a href="#/assessment/manual">Having trouble? Enter values manually</a><button class="text-button" data-action="explore-demo">Explore with fictional demo report</button></div></section></section><section class="welcome-how" id="how-it-works"><p class="eyebrow">Three simple steps</p><ol class="welcome-steps"><li><span>1</span><div><strong>Scan or upload your report</strong><small>FITSTART automatically reads the available FitMao values.</small></div></li><li><span>2</span><div><strong>Review and personalize</strong><small>Confirm the captured values and answer a few short questions.</small></div></li><li><span>3</span><div><strong>See what to review first</strong><small>Receive ranked focus areas with clear explanations.</small></div></li></ol></section><footer class="welcome-foot"><strong>Educational use only</strong><p>Uploaded image bytes remain in this browser session and are not sent to a real server. FITSTART does not diagnose conditions or replace advice from a qualified fitness professional.</p></footer></main>`}

export function authView(state={session:{signedIn:false}}){return `<main class="auth-page" id="main-content" tabindex="-1"><a class="brand" href="${state.latestResult?'#/results':'#/welcome'}"><span class="brand-mark">FS</span><span>FITSTART</span></a><section class="auth-card"><a class="back-link" href="${state.latestResult?'#/results':'#/welcome'}">← Back</a><p class="eyebrow">Optional account access</p><h1>${state.session.signedIn?"Your result is saved":"Save your results on this device"}</h1><p class="lead">Account access is simulated for this frontend prototype. No real Google or email service is connected.</p>${state.session.signedIn?`<div class="notice notice-info"><span>✓</span><div><strong>Prototype account active</strong><p>You can continue to your dashboard.</p></div></div><a class="button button-primary button-block" href="#/dashboard">Open Dashboard</a>`:`<button class="button button-google" data-action="prototype-google">Continue with Google <small>Prototype</small></button><div class="auth-tabs" role="tablist"><button type="button" class="is-active" data-auth-tab="create">Create Account</button><button type="button" data-auth-tab="signin">Sign In</button></div><form id="auth-form" data-mode="create"><div class="field"><label for="auth-email">Email address</label><input class="input" id="auth-email" name="email" type="email" value="${escapeHtml(state.profile?.email||fictionalDemoProfile.email)}" required></div><div class="field"><label for="auth-password">Password</label><input class="input" id="auth-password" name="password" type="password" minlength="8" required><small>Use any 8 characters for this simulation.</small></div><button class="button button-primary button-block" type="submit">Create Prototype Account</button><button class="text-button" type="button" data-action="forgot-password">Forgot password?</button></form><button class="text-button button-block" data-action="continue-guest">Continue without saving</button>`}<p class="fine-print">Prototype information stays in this browser. Do not use a real password.</p></section></main>`}

export function onboardingView(state){const p=state.profile||{},step=state.ui.onboardingStep||1;const body={1:`<div class="field"><label for="displayName">What should we call you?</label><input class="input" id="displayName" name="displayName" value="${escapeHtml(p.displayName||"")}" autocomplete="name" required><small>A first name or nickname is enough.</small></div>`,2:`<fieldset><legend>What is your main fitness goal?</legend><p class="field-help">Your goal helps FITSTART decide which report information is most relevant.</p><div class="choice-grid">${goalCards("primaryGoal",p.primaryGoal)}</div></fieldset><div class="field"><label for="secondaryGoal">Optional second goal</label><select class="select" id="secondaryGoal" name="secondaryGoal"><option value="">No second goal</option>${goalOptions.map(([v,t])=>`<option value="${v}" ${p.secondaryGoal===v?"selected":""}>${t}</option>`).join("")}</select></div>`,3:`<fieldset><legend>How much fitness-assessment experience do you have?</legend><p class="field-help">This changes how much explanation we show, not your ranking.</p><div class="choice-grid compact">${["new","somewhat-experienced","experienced"].map(v=>`<label class="choice-card"><input type="radio" name="fitnessExperience" value="${v}" ${p.fitnessExperience===v?"checked":""}><span><strong>${labels[v]}</strong></span></label>`).join("")}</div></fieldset>`,4:`<fieldset><legend>How familiar are you with body-composition terms?</legend><p class="field-help">We use this only to choose clearer or more concise explanations.</p><div class="choice-grid compact">${["not-familiar","somewhat-familiar","very-familiar"].map(v=>`<label class="choice-card"><input type="radio" name="assessmentFamiliarity" value="${v}" ${p.assessmentFamiliarity===v?"checked":""}><span><strong>${labels[v]}</strong></span></label>`).join("")}</div></fieldset>`}[step];return `<main class="page narrow" id="main-content">${stepper(1,["Your name","Your goals","Experience","Familiarity"])}<section class="card onboarding-card"><p class="eyebrow">Profile setup · Step ${step} of 4</p><h1 tabindex="-1">${["Let’s start with your name","What would you like to focus on?","Help us match the explanation to you","One last question"][step-1]}</h1><form id="onboarding-form" data-step="${step}">${body}<p class="field-error" data-error="onboarding" aria-live="polite"></p><div class="button-row spread">${step>1?'<button class="button button-secondary" type="button" data-action="onboarding-back">Back</button>':'<a class="button button-secondary" href="#/sign-in">Back</a>'}<button class="button button-primary" type="submit">${step===4?"Save Profile":"Continue"}</button></div></form></section></main>`}

export function personalizationView(state){const p=state.profile||{};return `<div class="page narrow">${pageHeader("Personalize your explanation","Tell us what matters to you","Your goals affect the order of focus areas. Experience and familiarity only change how much explanation you see.")}<form id="personalization-form" class="card personalization-form"><fieldset><legend>1. What is your primary fitness goal?</legend><div class="choice-grid">${goalCards("primaryGoal",p.primaryGoal)}</div></fieldset><div class="field"><label for="personal-secondary">2. Optional secondary goal</label><select class="select" id="personal-secondary" name="secondaryGoal"><option value="">No secondary goal</option>${goalOptions.map(([v,t])=>`<option value="${v}" ${p.secondaryGoal===v?"selected":""}>${t}</option>`).join("")}</select></div><fieldset><legend>3. How much fitness-assessment experience do you have?</legend><div class="choice-grid compact">${["new","somewhat-experienced","experienced"].map(v=>`<label class="choice-card"><input type="radio" name="fitnessExperience" value="${v}" ${p.fitnessExperience===v?"checked":""}><span><strong>${labels[v]}</strong></span></label>`).join("")}</div></fieldset><fieldset><legend>4. How familiar are you with assessment terms?</legend><div class="choice-grid compact">${["not-familiar","somewhat-familiar","very-familiar"].map(v=>`<label class="choice-card"><input type="radio" name="assessmentFamiliarity" value="${v}" ${p.assessmentFamiliarity===v?"checked":""}><span><strong>${labels[v]}</strong></span></label>`).join("")}</div></fieldset><p class="field-error" data-error="personalization" aria-live="polite" tabindex="-1"></p><div class="button-row spread"><a class="button button-secondary" href="#/assessment/review">Back to report</a><button class="button button-primary" type="submit">Continue</button></div></form></div>`}

export function dashboardView(state){
  const assessment=latest(state),result=ranking(state),main=result.mainFocus,history=state.assessments.slice().reverse();
  const name=assessment?.demographics?.displayName||state.profile?.displayName||"Member";
  if(!assessment)return `<div class="page">${emptyState("No assessment yet","Scan or upload a FitMao report to begin.","#/welcome","Go to Welcome")}</div>`;
  return `<div class="page"><header class="page-header"><div><p class="eyebrow">Dashboard</p><h1 tabindex="-1">Your assessment home</h1><p>Review your latest starting point and reopen a previous assessment.</p></div><a class="button button-primary" href="#/assessment/add">Add Another Assessment</a></header><section class="dashboard-member-hero"><div class="member-hero-head"><div><p class="eyebrow">Your profile</p><h2>Hi, ${escapeHtml(name)}</h2></div><div class="member-goal"><small>Current goal</small><strong>${label(state.profile?.primaryGoal)}</strong></div></div><div class="member-focus"><p class="eyebrow">Main focus</p><h3>${escapeHtml(main?.label||"Review the complete report")}</h3><p>${escapeHtml(main?.definition||"No single focus area clearly stands out from the available values.")}</p><p class="supporting">Latest assessment · ${formatDate(assessment.assessedAt)}</p></div><div class="member-hero-actions"><a class="button button-light button-large" href="#/results">View Personalized Results</a><a class="hero-text-link" href="#/profile">Edit goal</a></div></section><section class="section history-section"><div class="section-head history-head"><div><p class="eyebrow">Assessment history</p><h2>Your two newest reports</h2><p>${history.length} confirmed ${history.length===1?"report":"reports"} on this device.</p></div></div><div class="history-list">${history.map((item,index)=>historyCard(item,state,index===0)).join("")}</div></section></div>`;
}

export function assessmentAddView(state={}){const draft=state.importDraft;if(draft?.extractionStatus==="camera-ready")return `<div class="page narrow">${pageHeader("Scan FitMao QR","Place the report QR code inside the frame","Camera access is requested only after you choose Start Camera Scan.")}<section class="card qr-panel"><div class="scan-frame" aria-label="QR scanning frame"><span>⌗</span><p>FitMao QR code</p></div><div class="button-row"><button class="button button-primary" data-action="begin-camera">Start Camera Scan</button><button class="button button-secondary" data-action="use-simulated-qr">Use simulated QR result</button></div><button class="text-button" data-action="qr-not-found">Show QR-not-found recovery</button></section>${sourceNotice()}</div>`;if(draft?.extractionStatus==="failed")return `<div class="page narrow">${pageHeader("Report import needs attention","We could not continue with that source",draft.errorMessage||"Try the report again or choose another way to add it.")}${notice(draft.errorMessage||"The report could not be read.","warning","What happened")}<section class="card recovery-actions"><h2>Choose another option</h2><div class="button-row"><button class="button button-primary" data-action="retry-report">Try another report</button><button class="button button-secondary" data-action="request-upload" data-upload-input="report-upload">Upload report</button><a class="button button-secondary" href="#/assessment/manual">Enter values manually</a></div><input class="visually-hidden" id="report-upload" type="file" accept="image/png,image/jpeg,application/pdf"></section></div>`;return `<div class="page">${pageHeader("Add a FitMao assessment","Scan or upload your report","FITSTART will fill in the details it can identify. You will review and confirm them before they are used.")}<div class="source-grid"><article class="source-card"><span class="source-icon" aria-hidden="true">⌗</span><h2>Scan FitMao QR</h2><p>Use the QR code on your public FitMao report.</p><button class="button button-primary" data-action="request-qr">Scan report QR</button></article><article class="source-card"><span class="source-icon" aria-hidden="true">⇧</span><h2>Upload FitMao Report</h2><p>Choose ${ACCEPTED_REPORT_LABEL}.</p><button class="button button-primary" data-action="request-upload" data-upload-input="report-upload">Choose report file</button><input class="visually-hidden" id="report-upload" type="file" accept="image/png,image/jpeg,application/pdf"></article></div><div class="secondary-import-options"><a href="#/assessment/manual">Having trouble? Enter values manually</a><button class="text-button" data-action="explore-demo">Explore with fictional demo report</button></div>${sourceNotice()}</div>`}

export function importingView(state,previewUrl=""){const draft=state.importDraft||{},step=state.ui.importStep||0,steps=["Reading Report","Finding Fields","Structuring Values","Ready to Review"];return `<div class="page narrow">${pageHeader("Automatic report import","Reading your FitMao report","Keep this page open. Review begins automatically when the simulated extraction is ready.")}<section class="card import-progress"><div class="import-source">${sourcePreview(previewUrl,draft.fileName)}<div><small>${draft.sourceType==="qr-scan"?"QR status":"Selected file"}</small><strong>${escapeHtml(draft.fileName||"FitMao QR source")}</strong></div></div><ol class="extraction-steps">${steps.map((label,index)=>`<li class="${index<step?"is-done":index===step?"is-active":""}" data-import-step="${index}"><span>${index<step?"✓":index+1}</span><strong>${label}</strong></li>`).join("")}</ol><div class="button-row spread"><button class="button button-secondary" data-action="cancel-import">Cancel</button><button class="text-button" data-action="retry-report">Try another report</button></div></section>${notice("Automatic extraction is simulated in this frontend prototype. Always compare captured values with the FitMao report.","info","Prototype disclosure")}</div>`}

export function manualEntryView(state){const assessment=state.draftAssessment||{metrics:[]},details=assessment.demographics||{};return `<div class="page">${pageHeader("Manual entry fallback","Enter details from your FitMao report","Use this recovery option only when scanning or upload cannot capture the report. Everything still goes through Review and Verify.")}<form id="manual-form">${demographicFields(details)}<div class="required-key"><strong>Required to create a starting point</strong><span>Body weight · Body fat percentage · Muscle mass</span></div><div class="report-sections">${metricSections.map((section,index)=>`<details class="card report-section" ${index===0?"open":""}><summary><span><strong>${sectionTitle(section)}</strong><small>FitMao section: ${section}</small></span><span>${metricDefinitions.filter(m=>m.section===section).length} fields</span></summary><div class="manual-grid">${metricDefinitions.filter(m=>m.section===section).map(m=>`<div class="field"><label for="manual-${m.id}">${m.name}${["weight","pbf","smm"].includes(m.id)?" *":""}</label>${m.reportName&&m.reportName!==m.name?`<small>FitMao term: ${m.reportName}</small>`:""}<div class="input-with-unit"><input class="input" id="manual-${m.id}" name="${m.id}" ${typeof (assessment?.metrics.find(x=>x.id===m.id)?.value) === "number"?"type=number step=any":"type=text"} value="${escapeHtml(assessment?.metrics.find(x=>x.id===m.id)?.value??"")}"><span>${m.unit}</span></div><small>Report reference: ${m.range}</small></div>`).join("")}</div></details>`).join("")}</div><p class="field-error" data-error="manual" aria-live="polite"></p><div class="sticky-action"><button class="button button-secondary" type="button" data-action="save-manual">Save Draft</button><button class="button button-primary" type="submit">Continue to Review</button></div></form></div>`}

export function assessmentReviewView(state,previewUrl=""){const a=state.draftAssessment;if(!a)return `<div class="page">${emptyState("Nothing to review","Scan or upload your FitMao report first.","#/assessment/add","Scan or upload my report")}</div>`;const details=a.demographics||state.importDraft?.demographics||{};return `<div class="page wide">${pageHeader("Review and verify","Does this look right?","We filled in the available fields from your FitMao report. Please check them before continuing.")}<div class="review-layout"><details class="report-preview" open><summary>View source FitMao report</summary><div class="report-preview-body">${sourcePreview(previewUrl,a.fileName)}<div class="preview-controls"><button class="icon-button" type="button" data-action="preview-zoom-out" aria-label="Zoom report out">−</button><span data-zoom-label>100%</span><button class="icon-button" type="button" data-action="preview-zoom-in" aria-label="Zoom report in">+</button></div><p>${escapeHtml(a.fileName||"Fictional demonstration report")}</p><button class="text-button" type="button" data-action="retry-report">Replace this report</button></div></details><form id="review-form" class="metric-editor">${demographicFields(details)}${state.importDraft?.warnings?.length?notice(state.importDraft.warnings.join(" "),"warning","Some fields were not captured"):""}<div class="review-list">${metricSections.map((section,index)=>`<details class="review-section" ${index===0?"open":""}><summary><span><small>Report section ${index+1}</small><strong>${sectionTitle(section)}</strong></span><span>${a.metrics.filter(m=>m.section===section).length} values</span></summary><div>${a.metrics.filter(m=>m.section===section).map(m=>`<div class="edit-row"><div><label for="metric-${m.id}">${m.name}</label>${m.reportName&&m.reportName!==m.name?`<small>FitMao term: ${m.reportName}</small>`:""}<small>Printed FitMao reference: ${m.range}</small><span class="capture-state capture-${m.captureStatus||"extracted"}">${m.captureStatus==="missing"?"Not captured":m.captureStatus==="corrected"?"Corrected":"Captured"}</span></div><div class="input-with-unit"><input class="input" id="metric-${m.id}" name="metric-${m.id}" value="${escapeHtml(m.value)}" ${typeof m.value==="number"?'type="number" step="any"':'type="text"'}><span>${m.unit}</span></div><div class="field"><label for="status-${m.id}">Original report position</label><select class="select" id="status-${m.id}" name="status-${m.id}">${["Under","Normal","Over","Not provided","Report output","Original label"].map(v=>`<option ${m.status===v?"selected":""}>${v}</option>`).join("")}</select></div></div>`).join("")}</div></details>`).join("")}</div><label class="confirm-box"><input type="checkbox" name="reviewed" data-review-confirm><span><strong>I reviewed these values and they match my FitMao report.</strong><small>Correct any captured value that does not match before continuing.</small></span></label><p class="field-error" data-error="review" aria-live="polite" tabindex="-1"></p><div class="sticky-action"><a class="button button-secondary" href="#/assessment/add">Back</a><button class="button button-primary" type="submit" data-confirm-review disabled>Confirm Values and Continue</button></div></form></div>${notice("Automatic extraction is simulated in this frontend prototype. Always compare captured values with the FitMao report.","info","Prototype disclosure")}</div>`}

export function contextView(state){const p=state.profile,a=state.draftAssessment,details=a?.demographics||{};return `<div class="page narrow">${pageHeader("Final check","Your primary goal is "+label(p.primaryGoal)+". Is this correct?","Review the report details and answers FITSTART will use to organize your results.")}<section class="card final-summary"><div class="section-head"><div><p class="eyebrow">Member and report</p><h2>${escapeHtml(details.displayName||"Member")}</h2></div><button class="text-button" data-action="edit-assessment">Edit assessment</button></div><dl><div><dt>Age and gender</dt><dd>${escapeHtml(details.age||"Not provided")} · ${escapeHtml(details.gender||"Not provided")}</dd></div><div><dt>Height</dt><dd>${details.height?`${escapeHtml(details.height)} cm`:"Not provided"}</dd></div><div><dt>Assessment date</dt><dd>${formatDate(a.assessedAt)}</dd></div><div><dt>Primary goal</dt><dd>${label(p.primaryGoal)}</dd></div><div><dt>Secondary goal</dt><dd>${p.secondaryGoal?label(p.secondaryGoal):"No secondary goal"}</dd></div><div><dt>Fitness experience</dt><dd>${label(p.fitnessExperience)}</dd></div><div><dt>Assessment familiarity</dt><dd>${label(p.assessmentFamiliarity)}</dd></div></dl></section><div class="button-row spread"><a class="button button-secondary" href="#/personalize">Change My Answers</a><button class="button button-primary button-large" data-action="create-results">Yes, Create My Results</button></div></div>`}

export function processingView(){return `<div class="page processing-page"><div class="processing-mark">FS</div><p class="eyebrow">Rule-based processing</p><h1 tabindex="-1">Preparing your starting point</h1><ol class="processing-list">${["Checking confirmed FitMao values","Grouping related measurements","Matching focus areas with your goal","Ranking relevant focus areas","Preparing plain-language explanations"].map((text,i)=>`<li data-process="${i}"><span></span>${text}</li>`).join("")}</ol><p>FITSTART uses consistent demonstration rules. It does not diagnose, predict health outcomes, or create a workout or diet.</p></div>`}

export function resultsView(state){const a=latest(state),r=ranking(state);if(!a)return `<div class="page">${emptyState("No results yet","Scan or upload and verify a FitMao assessment first.","#/welcome","Go to Welcome")}</div>`;if(r.insufficient)return `<div class="page">${pageHeader("Personalized Starting Point","No single area clearly stands out","FITSTART could not identify one assessment area that clearly deserves greater attention from the available report. Review the complete results with a qualified fitness professional.")}${professionalNotice()}</div>`;const main=r.mainFocus,e=explainFocus(main,state.profile);return `<div class="page results-page">${pageHeader("Personalized Starting Point","What to review first","Assessment date · "+formatDate(a.assessedAt))}${notice("FITSTART organizes confirmed information from your report. It does not diagnose a condition or create a personal workout or diet plan.","info","Educational-use notice")}<article class="main-focus-card"><div><span class="pill light">Main Focus · Rank 1</span><h2>${main.label}</h2><p class="lead">${e.definition}</p><div class="evidence-chips">${main.supporting.slice(0,3).map(m=>`<span><strong>${m.name}</strong>${valueText(m)} · ${m.range!=="Chart band"?`Printed reference ${m.range}`:`Report position ${m.status}`}</span>`).join("")}</div><p>${e.recommendation}</p><a class="button button-light button-large" href="#/results/focus/${main.id}">See Full Explanation</a></div></article><section class="card why-card"><p class="eyebrow">Why This Ranked First</p><div class="why-grid"><div><span aria-hidden="true">1</span><strong>You told us</strong><p>${e.toldUs}</p></div><div><span aria-hidden="true">2</span><strong>Your FitMao report shows</strong><p>${e.showed}</p></div></div><p class="why-summary">${e.why}</p></section><section class="section"><div class="section-head"><div><p class="eyebrow">Ranked Priorities</p><h2>Other supported focus areas</h2><p>Related measurements stay grouped as evidence rather than separate priorities.</p></div></div><div class="focus-list">${r.priorities.map((f,i)=>focusCard(f,i+2)).join("")}</div></section>${professionalNotice()}<section class="result-actions"><a class="button button-primary" href="#/summary">Trainer Discussion Summary</a><a class="button button-secondary" href="#/report">View Complete FitMao Report</a><a class="button button-secondary" href="#/glossary">Open Glossary</a><a class="button button-secondary" href="#/dashboard">Open Dashboard</a>${!state.session.signedIn?'<a class="button button-secondary" href="#/sign-in">Save Results</a>':""}</section></div>`}

export function historyResultView(state,id){const a=state.assessments.find(item=>item.id===id);if(!a)return `<div class="page">${emptyState("Assessment not found","This report may no longer be saved on this device.","#/dashboard","Back to assessment history")}</div>`;const r=rankFocusAreas(a,state.profile),main=r.mainFocus,isNewest=a.id===latest(state)?.id;if(r.insufficient)return `<div class="page"><nav class="breadcrumbs"><a href="#/dashboard">Home</a><span>/</span><span>Assessment history</span></nav>${pageHeader("Assessment history",formatDate(a.assessedAt),"There are not enough confirmed values to identify a starting point.",'<a class="button button-secondary" href="#/dashboard">Back to history</a>')}${professionalNotice()}</div>`;const e=explainFocus(main,state.profile);return `<div class="page results-page history-result-page"><nav class="breadcrumbs"><a href="#/dashboard">Home</a><span>/</span><span>Assessment history</span></nav>${pageHeader(isNewest?"Newest saved assessment":"Earlier saved assessment",formatDate(a.assessedAt),`Interpreted using your current goal: ${label(state.profile.primaryGoal)}.`, '<a class="button button-secondary" href="#/dashboard">Back to history</a>')}<article class="main-focus-card history-main-focus"><div><span class="pill light">Starting point</span><h2>${main.label}</h2><p class="lead">${e.definition}</p><div class="evidence-chips">${main.supporting.slice(0,3).map(m=>`<span><strong>${m.name}</strong>${valueText(m)} · Report says ${m.status}</span>`).join("")}</div></div></article>${notice("This is a saved report from your assessment history. Your original values have not been changed.","info","Saved assessment")}<section class="card why-card"><p class="eyebrow">How this was organized</p><div class="why-grid"><div><span aria-hidden="true">1</span><strong>Your current goal</strong><p>${e.toldUs}</p></div><div><span aria-hidden="true">2</span><strong>This report</strong><p>${e.showed}</p></div></div><p class="why-summary">${e.why}</p></section><section class="section"><div class="section-head"><div><p class="eyebrow">Review next</p><h2>Other useful areas from this report</h2></div></div><div class="history-priority-list">${r.priorities.map((focus,index)=>`<article class="card history-priority"><span>${index+2}</span><div><small>Review next</small><h3>${focus.label}</h3><p>${focus.definition}</p></div></article>`).join("")}</div></section>${professionalNotice()}<div class="result-actions"><a class="button button-primary" href="#/dashboard">Back to assessment history</a>${state.assessments.length>1?'<a class="button button-secondary" href="#/compare">Compare saved reports</a>':""}<a class="button button-secondary" href="#/assessment/add">Add another report</a></div></div>`}

export function focusDetailView(state,id){const r=ranking(state),focus=r.items.find(item=>item.id===id);if(!focus)return `<div class="page">${emptyState("Result not found","Return to your starting point and choose another area.","#/results","Back to my results")}</div>`;const e=explainFocus(focus,state.profile),rank=r.items.findIndex(item=>item.id===id)+1;return `<div class="page"><nav class="breadcrumbs"><a href="#/results">My results</a><span>/</span><span>${focus.label}</span></nav>${pageHeader(rank===1?"Your starting point":`Review next · ${rank}`,focus.label,e.definition)}<div class="detail-grid"><div class="stack"><section class="card explanation-stack"><div><span>1</span><div><h2>Your goal</h2><p>${e.toldUs}</p></div></div><div><span>2</span><div><h2>Your report</h2><p>${e.showed}</p></div></div><div><span>3</span><div><h2>Why it appears here</h2><p>${e.why}</p></div></div></section><section class="card"><h2>Values behind this result</h2><p>These measurements support the same result. They are not separate priorities.</p><div class="metric-lines">${focus.supporting.map(metricRow).join("")}</div></section><section class="recommendation"><span>→</span><div><h2>What to discuss</h2><p>${e.recommendation}</p></div></section></div><aside class="stack">${professionalNotice()}${state.ui.researchMode?`<details class="card research-details"><summary>Research scoring details</summary><p>${rankingNotice}</p><dl><div><dt>Report evidence</dt><dd>${focus.evidence}</dd></div><div><dt>Main-goal relevance</dt><dd>${focus.primary}</dd></div><div><dt>Second-goal relevance</dt><dd>${focus.secondary}</dd></div><div><dt>Total score</dt><dd>${focus.score}</dd></div></dl></details>`:""}</aside></div></div>`}

export function summaryView(state){const a=latest(state),r=ranking(state);if(!a)return `<div class="page">${emptyState("No discussion guide yet","Confirm a report first to prepare your guide.","#/assessment/add","Add my report")}</div>`;return `<div class="page print-page">${pageHeader("Guide for talking with your trainer",`${state.profile.displayName}’s report notes`,`Prepared from the FitMao report you confirmed on ${formatDate(a.assessedAt)}.`,`<button class="button button-secondary" data-action="print-summary">Print guide</button>`)}<section class="paper"><div class="summary-top"><div><small>Your main goal</small><strong>${label(state.profile.primaryGoal)}</strong></div><div><small>Report date</small><strong>${formatDate(a.assessedAt)}</strong></div></div><section><p class="eyebrow">Start here</p><h2>${r.mainFocus?.label||"No clear starting point"}</h2></section><section><h2>What to review next</h2><ol>${r.priorities.map(f=>`<li>${f.label}</li>`).join("")||"<li>No additional results need review</li>"}</ol></section><section><h2>Important values from your report</h2><div class="metric-lines">${r.mainFocus?.supporting.slice(0,4).map(metricRow).join("")||""}</div></section><section><h2>Questions to ask your trainer</h2><ul><li>What do these results mean for my goal?</li><li>Which exercise and nutrition options are suitable for me?</li><li>How can I make future measurements more consistent?</li></ul></section>${professionalNotice()}</section></div>`}

export function fullReportView(state){const a=latest(state),previous=state.assessments.at(-2);if(!a)return `<div class="page">${emptyState("No confirmed report","Add and confirm a report first.","#/assessment/add","Add my report")}</div>`;return `<div class="page wide">${pageHeader("All report values","Your confirmed FitMao information","Use this page when you want to check every value. FITSTART keeps the original FitMao terms beside simpler names.")}<div class="report-layout"><aside class="report-sidebar"><img src="assets/images/sample-fitmao-report.svg" alt="Example FitMao report layout"><nav>${metricSections.map((s,i)=>`<a href="#report-section-${i}">${sectionTitle(s)}</a>`).join("")}${previous?'<a href="#report-history">Earlier report</a>':""}</nav></aside><div class="report-content">${a.notice?notice(a.notice,"info","Test values"):""}${metricSections.map((section,i)=>`<section class="card report-table" id="report-section-${i}"><h2>${sectionTitle(section)}</h2><small>FitMao section: ${section}</small><div class="metric-lines">${a.metrics.filter(m=>m.section===section).map(metricRow).join("")}</div></section>`).join("")}${previous?`<section class="card report-table" id="report-history"><h2>Earlier report</h2><p>Confirmed on ${formatDate(previous.assessedAt)}</p><div class="metric-lines">${previous.metrics.slice(0,8).map(metricRow).join("")}</div></section>`:""}${professionalNotice()}</div></div></div>`}

export function glossaryView(){const categories=[...new Set(glossaryData.map(item=>item.category))];return `<div class="page">${pageHeader("Glossary","Understand the terms on your report","Search for a metric or browse by category. Definitions explain the report without diagnosing you.")}<div class="search-tools"><div class="field"><label for="glossary-search">Search the glossary</label><input class="input" id="glossary-search" type="search" placeholder="Try “body fat” or “BMI”"></div><div class="filters" aria-label="Glossary categories"><button class="is-active" data-glossary-filter="all">All</button>${categories.map(c=>`<button data-glossary-filter="${c}">${c}</button>`).join("")}</div></div><section class="glossary-grid">${glossaryData.slice().sort((a,b)=>a.name.localeCompare(b.name)).map(item=>`<article class="card glossary-card" data-glossary-card data-name="${escapeHtml(`${item.name} ${item.abbr}`.toLowerCase())}" data-category="${item.category}"><span class="pill">${item.category}</span><h2>${item.name}</h2><p>${item.definition}</p><a href="#/glossary/${item.id}">Read definition →</a></article>`).join("")}</section><section id="glossary-empty" class="card empty-state" hidden><h2>No matching term</h2><p>Try a shorter word or choose All.</p></section></div>`}

export function glossaryDetailView(state,id){const item=glossaryEntry(id);if(!item)return `<div class="page">${emptyState("Term not found","Return to Learn Terms and choose another measurement.","#/glossary","Learn report terms")}</div>`;const reportTerm=item.reportName||item.name;return `<div class="page narrow"><nav class="breadcrumbs"><a href="#/glossary">Learn Terms</a><span>/</span><span>${item.name}</span></nav>${pageHeader(item.category,item.name,reportTerm!==item.name?`FitMao calls this “${reportTerm}”${item.abbr!=="—"?` (${item.abbr})`:""}.`:item.abbr!=="—"?`You may see “${item.abbr}” on your report.`:"A plain-language guide to this measurement.")}<section class="card definition-hero"><p class="eyebrow">In simple terms</p><h2>${item.definition}</h2></section><section class="card info-sections"><div><h2>What appears on the report</h2><p>${item.reports}</p></div><div><h2>What to keep in mind</h2><p>${item.limitation}</p></div><details><summary>Reference information for researchers</summary><p>${item.source}</p></details></section>${item.related.length?`<section><h2>Related terms</h2><div class="related-links">${item.related.map(r=>{const m=glossaryEntry(r);return `<a class="card" href="#/glossary/${r}">${m.name} →</a>`}).join("")}</div></section>`:""}</div>`}

export function compareView(state){if(state.assessments.length<2)return `<div class="page">${emptyState("Compare is not available yet","Add and confirm a second FitMao assessment to compare your two newest reports.","#/assessment/add","Add second assessment")}</div>`;const [previous,current]=state.assessments.slice(-2),rows=compareAssessments(previous,current,state.profile.primaryGoal);return `<div class="page">${pageHeader("Limited comparison","Your two newest confirmed reports","This view compares measured values only. It does not prove improvement or failure.")}<div class="date-compare"><div><small>Previous</small><strong>${formatDate(previous.assessedAt)}</strong></div><span>→</span><div><small>Current</small><strong>${formatDate(current.assessedAt)}</strong></div></div><section class="card comparison-table">${rows.map(row=>`<div class="comparison-row"><div><strong>${row.name}</strong><small>${row.changeLabel}</small></div><span>${row.previousValue} ${row.unit}</span><span>→</span><span>${row.currentValue} ${row.unit}</span><strong class="difference">${row.difference>0?"+":""}${row.difference} ${row.unit}</strong><p>${row.supportsGoal?`This movement is in the direction of your stated ${label(state.profile.primaryGoal)} goal.`:"No approved goal-direction statement is shown for this change."}${row.large?" Large difference detected. Verify both FitMao reports before interpreting the change.":""}</p></div>`).join("")}</section>${notice("Measurement conditions may affect body-composition results. Try to compare reports taken under similar conditions.","warning","Measurement variability")}${professionalNotice()}</div>`}

export function profileView(state){const p=state.profile;return `<div class="page">${pageHeader("Profile and settings","Your saved details","Update the context FITSTART uses to organize your confirmed report.")}<div class="settings-grid"><form class="card" id="profile-form"><div class="field"><label for="profile-name">Name</label><input class="input" id="profile-name" name="displayName" value="${escapeHtml(p.displayName)}"></div><div class="field"><label for="profile-email">Demo email</label><input class="input" id="profile-email" value="${escapeHtml(p.email||"No saved email — guest mode")}" disabled></div><div class="field"><label for="profile-goal">Primary goal</label><select class="select" id="profile-goal" name="primaryGoal">${goalOptions.map(([v,t])=>`<option value="${v}" ${p.primaryGoal===v?"selected":""}>${t}</option>`).join("")}</select></div><div class="field"><label for="profile-secondary">Optional secondary goal</label><select class="select" id="profile-secondary" name="secondaryGoal"><option value="">No secondary goal</option>${goalOptions.map(([v,t])=>`<option value="${v}" ${p.secondaryGoal===v?"selected":""}>${t}</option>`).join("")}</select></div><div class="field"><label for="profile-experience">Fitness experience</label><select class="select" id="profile-experience" name="fitnessExperience">${selectOptions(["new","somewhat-experienced","experienced"],p.fitnessExperience)}</select></div><div class="field"><label for="profile-familiarity">Assessment familiarity</label><select class="select" id="profile-familiarity" name="assessmentFamiliarity">${selectOptions(["not-familiar","somewhat-familiar","very-familiar"],p.assessmentFamiliarity)}</select></div><p class="field-error" data-error="profile" aria-live="polite"></p><button class="button button-primary" type="submit">Edit Profile</button></form><aside class="stack"><section class="card"><h2>More</h2><a class="settings-link" href="#/report">Full FitMao Report <span>→</span></a><a class="settings-link ${state.assessments.length<2?"is-disabled":""}" href="${state.assessments.length<2?"#/profile":"#/compare"}" ${state.assessments.length<2?'aria-disabled="true"':""}>Compare <span>${state.assessments.length<2?"Add a second report":"→"}</span></a>${!state.session.signedIn?'<a class="settings-link" href="#/sign-in">Save Results <span>→</span></a>':""}<button class="settings-link" data-action="sign-out">Sign Out <span>→</span></button></section><details class="card researcher-tools"><summary>Research Mode</summary><p>Optional details for prototype evaluators.</p><label class="toggle"><input type="checkbox" data-action="toggle-research" ${state.ui.researchMode?"checked":""}><span></span>Show demonstration rules and scores</label>${state.ui.researchMode?'<a class="button button-secondary button-block" href="#/research-comparison">Open Research Comparison</a>':""}</details><section class="card danger-zone"><h2>Local demo data</h2><p>Your profile and two newest assessments stay only in this browser during testing.</p><button class="button button-danger" data-action="clear-data">Clear Demo Data</button></section></aside></div></div>`}

export function researchView(state){const a=latest(state),r=ranking(state);if(!state.ui.researchMode)return `<div class="page">${emptyState("Researcher tools are off","Turn them on in My Profile to view the interface comparison.","#/profile","Open my profile")}</div>`;return `<div class="page wide">${pageHeader("Interface research comparison","FitMao layout and FITSTART layout","Both views use the same report values so prototype evaluators can compare how the information is presented.")}<div class="research-tabs" role="tablist"><button class="is-active" data-research-tab="original">FitMao layout</button><button data-research-tab="fitstart">FITSTART layout</button></div><div class="research-split"><section data-research-panel="original" class="is-active"><h2>FitMao report layout</h2><img src="assets/images/sample-fitmao-report.svg" alt="Example FitMao report layout"><div class="metric-lines">${a?.metrics.slice(0,8).map(metricRow).join("")||""}</div></section><section data-research-panel="fitstart"><h2>FITSTART layout</h2>${r.mainFocus?focusCard(r.mainFocus,1):"<p>No starting point available.</p>"}<div class="focus-list">${r.priorities.map((f,i)=>focusCard(f,i+2)).join("")}</div></section></div><p class="fine-print">${rankingNotice}</p></div>`}

export function notFoundView(){return `<div class="page">${emptyState("We could not find that page","Use the dashboard to continue your FITSTART journey.","#/dashboard","Go to Dashboard")}</div>`}
